      "module": "Mathlib.Data.Finsupp.Defs"
    },
    {
      "name": "Finsupp.ofSupportFinite_support",
      "type": " {α : Type u_1} {M : Type u_4} [Zero M] {f : α → M} (hf : (Function.support f).Finite) : (Finsupp.ofSupportFinite f hf).support = hf.toFinset",
      "module": "Mathlib.Data.Finsupp.Defs"
    },
    {
      "name": "Finsupp.support_embDomain",
      "type": " {α : Type u_1} {β : Type u_2} {M : Type u_4} [Zero M] (f : α ↪ β) (v : α →₀ M) : (Finsupp.embDomain f v).support = Finset.map f v.support",
      "module": "Mathlib.Data.Finsupp.Defs"
    },
    {
      "name": "Finsupp.support_nonempty_iff",
      "type": " {α : Type u_1} {M : Type u_4} [Zero M] {f : α →₀ M} : f.support.Nonempty ↔ f ≠ 0",
      "module": "Mathlib.Data.Finsupp.Defs"
    },
    {
      "name": "Finsupp.fun_support_eq",
      "type": " {α : Type u_1} {M : Type u_4} [Zero M] (f : α →₀ M) : Function.support ⇑f = ↑f.support",
      "module": "Mathlib.Data.Finsupp.Defs"
    },
    {
      "name": "Finsupp.mem_support_toFun",
      "type": " {α : Type u_8} {M : Type u_9} [Zero M] (self : α →₀ M) (a : α) : a ∈ self.support ↔ self.toFun a ≠ 0",
      "module": "Mathlib.Data.Finsupp.Defs"
    },
    {
      "name": "Finsupp.onFinset_support",
      "type": " {α : Type u_1} {M : Type u_4} [Zero M] (f : α →₀ M) : Finsupp.onFinset f.support ⇑f ⋯ = f",
      "module": "Mathlib.Data.Finsupp.Defs"
    }
  ]
}
